/// <reference path="../pb_data/types.d.ts" />

/**
 * Ограничение попыток входа по одному адресу почты.
 *
 * Встроенный лимитер считает по адресу клиента, и перебор одного ящика с
 * десятка машин он не заметит: с каждой придёт по паре запросов. Считаем то,
 * что перебирают, — сам ящик.
 *
 * Блокируются попытки входа, а не учётная запись. Иначе любой посторонний,
 * зная только адрес почты, запирает человека снаружи; поэтому и сроки здесь
 * минутные, а не часовые.
 *
 * Ответ одинаков для существующего и несуществующего адреса: разный ответ
 * превратил бы перебор в проверку, кто у нас зарегистрирован.
 *
 * Считаем и вход администратора (_superusers). Он идёт по своему адресу, и
 * пока обработчик висел на одной users, самый дорогой пароль в системе —
 * тот, что открывает базу целиком, — перебирался без всяких ограничений.
 * Счётчики коллекций держим врозь: иначе постороннему хватало бы стучаться
 * в открытую всем дверь users, чтобы закрыть вход в админку, а человек,
 * забывший пароль в приложении, запирал бы одноимённого администратора.
 *
 * Счётчики живут в $app.store() — это встроенное потокобезопасное хранилище
 * в памяти сервера, общее для всех обработчиков. Перезапуск их обнуляет, и
 * это осознанно: своего хранилища ради перебора, который после перезапуска
 * начнётся заново и снова упрётся в тот же счётчик, заводить незачем.
 *
 * ВАЖНО, ПРЕЖДЕ ЧЕМ ПРАВИТЬ. Обработчик исполняется в отдельной машине, и
 * окружающий файл ему недоступен: вынесенный наружу помощник даёт
 * ReferenceError на каждом запросе. Поэтому всё объявлено внутри. Любую
 * правку гонять на стенде — см. «Проверка обработчиков» в DEPLOY.md.
 */

onRecordAuthWithPasswordRequest((e) => {
  // Ступени: сколько неудач подряд — на сколько секунд закрываем вход.
  const STEPS = [
    { fails: 15, lock: 15 * 60 },
    { fails: 10, lock: 5 * 60 },
    { fails: 5, lock: 60 },
  ]
  // Счётчик без новых неудач столько живёт. Забытый пароль, набранный
  // трижды с утра и дважды вечером, блокировкой считаться не должен.
  const FORGET = 60 * 60
  // Потолок числа отслеживаемых адресов: перебор по случайным ящикам иначе
  // растил бы память сервера без предела.
  const MAX_TRACKED = 20000

  const store = $app.store()
  const now = Math.floor(Date.now() / 1000)

  // Ключ — то, что человек ввёл, приведённое к общему виду: иначе Ivan@x.ru
  // и ivan@x.ru считались бы разными ящиками, а вход по ним один. Коллекция
  // в ключе разводит вход в приложение и вход в админку: адрес может быть
  // один и тот же, а двери разные.
  const where = e.collection ? e.collection.name : ''
  const key = 'login:' + where + ':' + String(e.identity || '').trim().toLowerCase()

  const state = store.get(key)
  const fails = state && state.until > now - FORGET ? state.fails : 0
  const until = state ? state.until : 0

  if (until > now) {
    throw new TooManyRequestsError(
      'Слишком много попыток входа. Попробуйте позже.',
      { seconds: until - now },
    )
  }

  try {
    e.next()
  } catch (err) {
    const next = fails + 1
    let lock = 0
    for (const step of STEPS) {
      if (next >= step.fails) {
        lock = step.lock
        break
      }
    }
    // setIfLessThanLimit не даёт хранилищу расти без предела: когда потолок
    // достигнут, новые адреса просто не отслеживаются. Уже отслеживаемые
    // при этом продолжают считаться — обновление существующего ключа
    // проходит независимо от потолка.
    store.setIfLessThanLimit(key, { fails: next, until: now + lock }, MAX_TRACKED)
    throw err
  }

  // Вошёл — счётчик больше не нужен: перебор не заканчивается удачей.
  store.remove(key)
}, 'users', '_superusers')
